#!/usr/bin/env node
// Copy the app icons (src-tauri/icons) into the mobile project generated by `tauri android init` or
// `tauri ios init`. The generated projects (src-tauri/gen, not in git) start with Tauri's default icons:
// without this step the Android and iPhone/iPad apps do not show the Referto Volley logo.
// Usage: node scripts/mobile-icons.mjs android|ios   (after the init, before the build)
import { cpSync, existsSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const TARGETS = {
  // mipmap-* (legacy and adaptive icon), mipmap-anydpi-v26/ic_launcher.xml, values/ic_launcher_background.xml
  android: { from: 'src-tauri/icons/android', to: 'src-tauri/gen/android/app/src/main/res' },
  // AppIcon-<size>@<scale>.png: the names listed in the Contents.json of the generated asset catalog
  ios: { from: 'src-tauri/icons/ios', to: 'src-tauri/gen/apple/Assets.xcassets/AppIcon.appiconset' },
}

const platform = process.argv[2]
const target = TARGETS[platform]
if (!target) {
  console.error('Uso: node scripts/mobile-icons.mjs android|ios')
  process.exit(1)
}
const to = join(root, target.to)
if (!existsSync(to)) {
  console.error(`Progetto ${platform} non generato (${target.to} non esiste): esegui prima "npm run tauri -- ${platform} init".`)
  process.exit(1)
}
cpSync(join(root, target.from), to, { recursive: true })
const count = readdirSync(join(root, target.from), { recursive: true }).filter(name => String(name).endsWith('.png')).length
console.log(`Icone ${platform}: ${count} immagini copiate in ${target.to}`)
